insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod05$wdthseed$, $wdthseed$Genetics$wdthseed$, $wdthseed$How traits pass from parents to children: Mendel's laws, Punnett squares, and inheritance beyond simple dominance.$wdthseed$, 5, $wdthseed${"objectives":["Use the vocabulary of inheritance correctly","Solve monohybrid crosses including sex-linked traits","Explain incomplete dominance, codominance and blood groups"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod05:top01$wdthseed$, $wdthseed$Mendel and Inheritance$wdthseed$, $wdthseed$Genes, alleles and genotypes; Mendel's pea experiments and the 3:1 ratio.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["Define genetic terms","Solve monohybrid crosses"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod05:top01:les01$wdthseed$, $wdthseed$Genes, Alleles and Genotypes$wdthseed$, $wdthseed$The vocabulary of inheritance and how Mendel discovered its rules.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=pv3Kj0UjiLE$wdthseed$, $wdthseed$Why do you resemble your parents but match neither exactly? In a monastery garden in the 1860s, Gregor Mendel grew 29,000 pea plants and found the mathematical rules behind the answer.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The vocabulary$wdthseed$, $wdthseed$A GENE is a DNA section coding for one trait (e.g. seed shape). An ALLELE is one version of a gene (round R vs wrinkled r). GENOTYPE is the allele pair an organism carries (RR, Rr, rr); PHENOTYPE is the observable trait (round or wrinkled). DOMINANT alleles show in heterozygotes (Rr looks round); RECESSIVE alleles show only when homozygous (rr). HOMOZYGOUS = identical alleles (RR or rr); HETEROZYGOUS = different alleles (Rr). CARRIERS (e.g. HbAHbS) carry a recessive allele without showing it. Mendel's genius was METHOD: he used pure-breeding lines, crossed them, counted THOUSANDS of offspring, and tracked ONE trait at a time. Peas were perfect: fast-growing, self- or cross-pollinating, with sharply contrasting traits (tall/short, round/wrinkled, green/yellow).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The 3:1 ratio$wdthseed$, $wdthseed$Cross pure tall (TT) with pure short (tt): all F1 offspring are Tt (all tall — dominance hides t). Self-cross the F1 (Tt × Tt): the F2 generation averages 3 tall : 1 short. Mendel's explanation — the LAW OF SEGREGATION: allele pairs separate into different gametes during meiosis, so each gamete carries ONE allele, and pairs reunite randomly at fertilisation. The wrinkled trait never blended away — it was CARRIED invisibly and reappeared. This disproved blending inheritance and founded genetics. His second law — INDEPENDENT ASSORTMENT: different gene pairs assort independently (Module 4's metaphase I lottery) — holds for genes on different chromosomes.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the F2 ratio$wdthseed$, $wdthseed$Question: In tomatoes, red fruit (R) is dominant over yellow (r). Two heterozygous red plants are crossed. Predict the offspring ratio. Step 1 — Parent genotypes: Rr × Rr. Step 2 — Gametes: each parent makes R and r (segregation). Step 3 — Punnett square: rows R, r × columns R, r gives RR, Rr, Rr, rr. Step 4 — Phenotypes: 3 red : 1 yellow; genotypes 1 RR : 2 Rr : 1 rr. Examination format: ALWAYS show parents, gametes, square, then genotype AND phenotype ratios — each line earns marks. Use the correct case convention (dominant capital, recessive lowercase of the SAME letter).$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Alleles and Genes$wdthseed$, $wdthseed$Watch 'Alleles and Genes' by the Amoeba Sisters (official channel stream). Pause and define all eight vocabulary terms from memory before continuing.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=pv3Kj0UjiLE$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Gene = trait unit; allele = version; genotype = pair carried; phenotype = trait seen.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Mendel counted peas and discovered that inheritance comes in discrete units that segregate and reassort. Eight vocabulary terms and the 3:1 ratio are the keys to every genetics calculation ahead.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
