insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod05:top01:les01:vid1:res$wdthseed$, $wdthseed$Alleles and Genes$wdthseed$, $wdthseed$Core inheritance vocabulary with clear visual examples.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=pv3Kj0UjiLE$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod05:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod05:top01:les02$wdthseed$, $wdthseed$Solving Monohybrid Crosses$wdthseed$, $wdthseed$A five-step method for every single-trait cross, including test crosses and pedigrees.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Genetics problems look frightening until you learn the method. With five disciplined steps, every monohybrid cross — in homework, WAEC or JAMB — surrenders.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The five-step method$wdthseed$, $wdthseed$STEP 1 — SYMBOLS: assign letters (dominant capital: A; recessive lowercase: a) and state what each means. STEP 2 — PARENTS: write both genotypes with phenotypes (e.g. Aa tall × aa short). STEP 3 — GAMETES: list each parent's possible gametes (Aa makes A and a; aa makes only a). STEP 4 — SQUARE: draw the Punnett grid, fill every box. STEP 5 — RATIOS: state genotype ratio AND phenotype ratio (or probabilities). TEST CROSS: to reveal an unknown dominant phenotype (A? ), cross with homozygous recessive (aa) — if ANY recessive offspring appear, the parent was heterozygous; if dozens of offspring are all dominant, it is almost certainly AA. PEDIGREES: dominant traits appear every generation (affected children always have an affected parent); recessive traits skip generations and appear from carrier parents; if two normal parents have an affected child, the trait MUST be recessive.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the mystery bull$wdthseed$, $wdthseed$Question: In cattle, hornless (H) is dominant over horned (h). A hornless bull is mated with horned cows (hh) and produces 12 calves — 6 hornless, 6 horned. What is the bull's genotype? Step 1 — Symbols: H hornless, h horned. Step 2 — Parents: bull H? × hh cows. Step 3 — Reason: horned calves (hh) must get h from EACH parent, so the bull carries h → the bull is Hh. Step 4 — Check: Hh × hh predicts 1:1, matching the observed 6:6. Step 5 — Conclude: heterozygous (Hh), proven by a test cross. Notice: the RECESSIVE offspring revealed the hidden allele — this logic cracks every 'find the genotype' question.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: pedigree reading$wdthseed$, $wdthseed$Question: A pedigree shows normal parents with one affected son and one normal daughter. Is the trait dominant or recessive? Step 1 — Test dominant: a dominant trait needs an affected parent to pass the allele — but BOTH parents are normal, so dominant is IMPOSSIBLE. Step 2 — Test recessive: two carrier parents (Aa × Aa) can produce aa children — possible. Step 3 — Conclude: recessive; both parents are carriers, the son is aa, the daughter is AA or Aa. Golden rule: normal parents + affected child = RECESSIVE, always. (Affected parent + normal children in every generation suggests dominant.)$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Five steps: symbols → parents → gametes → square → ratios.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Monohybrid crosses yield to method: symbols, parents, gametes, square, ratios. Test crosses expose hidden alleles, and pedigrees reveal dominance patterns — normal parents with an affected child always means recessive.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod05:top02$wdthseed$, $wdthseed$Beyond Simple Dominance$wdthseed$, $wdthseed$Incomplete dominance, codominance, blood groups and sex-linked inheritance.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Explain non-Mendelian patterns","Solve blood-group and sex-linked crosses"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod05:top02:les01$wdthseed$, $wdthseed$Incomplete Dominance and Blood Groups$wdthseed$, $wdthseed$When heterozygotes blend or show both alleles — snapdragons, sickle cell and ABO.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Red snapdragon × white snapdragon gives... pink. Neither allele dominates — Mendel's rules still apply, but dominance itself has shades.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Three dominance patterns$wdthseed$, $wdthseed$COMPLETE DOMINANCE: heterozygote matches one parent (Tt peas are tall). INCOMPLETE DOMINANCE: heterozygote is INTERMEDIATE — red snapdragon (CRCR) × white (CWCW) gives all pink (CRCW); self-crossing pinks gives 1 red : 2 pink : 1 white (note: use SUPERSCRIPT letters, never Rr, to avoid implying dominance). CODOMINANCE: heterozygote shows BOTH traits fully — roan cattle (red + white hairs), and human AB blood (both A and B antigens). MULTIPLE ALLELES: more than two alleles exist in the population — ABO blood has THREE (IA, IB, i): IA and IB are codominant with each other, both dominant over i. Genotypes: group A = IAIA or IAi; B = IBIB or IBi; AB = IAIB; O = ii (universal donor — no antigens; AB is universal recipient — no antibodies).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Sickle cell: dominance depends on the level$wdthseed$, $wdthseed$Sickle-cell anaemia shows dominance beautifully: at the MOLECULAR level, HbAHbS carriers make both normal and sickle haemoglobin (codominance); at the ORGANISM level in normal air, carriers look healthy (recessive disease); under severe oxygen shortage, carriers can show symptoms (incomplete dominance). One gene, three answers — dominance describes RELATIONSHIPS, not alleles alone. In malaria regions, carriers survive best (heterozygote advantage — the final-exam favourite), keeping the HbS allele common despite the disease. Genetic counselling lets carrier couples understand their 1-in-4 risk per pregnancy.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: blood-group cross$wdthseed$, $wdthseed$Question: A group-A mother (genotype IAi) and group-B father (IBi) have children. What blood groups are possible? Step 1 — Gametes: mother IA or i; father IB or i. Step 2 — Square: IAIB (AB), IAi (A), IBi (B), ii (O). Step 3 — Conclude: ALL FOUR groups possible — A, B, AB and O, each 1/4. Transfusion rule to memorise: give red cells lacking antigens the recipient's antibodies attack — O donates to all (no antigens); AB receives from all (no antibodies). Rh factor adds a second check in real medicine.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Incomplete = blended heterozygote (pink snapdragons, 1:2:1). Codominant = both shown (roan, AB blood).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Dominance is a relationship, not a property: alleles can dominate, blend or share. ABO blood groups combine multiple alleles with codominance, and sickle cell proves that the same gene can show every pattern at once.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod05:top02:les02$wdthseed$, $wdthseed$Sex-Linked Inheritance$wdthseed$, $wdthseed$Why haemophilia and colour blindness mostly affect males — genes on the X chromosome.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=jLmoJPxihjA$wdthseed$, $wdthseed$Queen Victoria's descendants carried haemophilia across Europe's royal families — through daughters who never bled, to sons who did. The X chromosome explains it all.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$X-linked recessive logic$wdthseed$, $wdthseed$Females are XX, males XY. The X carries 1000+ genes (including blood-clotting factor VIII and colour-vision genes); the tiny Y carries few, mostly male-determining. An X-linked RECESSIVE allele (Xh) shows in females only when homozygous (XhXh) but in males with a SINGLE copy (XhY) — males have no second X to mask it. Hence: males affected far more often; affected fathers pass Xh to ALL daughters (making them carriers) but NEVER to sons (sons get Y from father); carrier mothers pass to HALF their sons (affected) and half their daughters (carriers). Colour blindness (red-green) follows identical logic and is the commonest example (~8% of males). Notation: always write XHXH, XHXh, XhXh, XHY, XhY — bare 'Hh' loses marks in sex-linked questions.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the carrier mother$wdthseed$, $wdthseed$Question: A normal-vision woman whose father was colour-blind marries a normal-vision man. What proportion of their sons will be colour-blind? Step 1 — Deduce her genotype: her father (XhY) gave her his ONLY X (Xh), so she is XHXh (carrier) — her normal vision proves the XH. Step 2 — Cross: XHXh × XHY. Step 3 — Sons: get Y from father, XH or Xh from mother → HALF the sons (XhY) colour-blind. Step 4 — Note daughters: all get XH from father, so all see normally (half carriers). Examination trap: 'father to son' transmission of X-linked traits is IMPOSSIBLE — any pedigree showing it rules out X-linkage.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les02:blk03$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Mega Genetics Review$wdthseed$, $wdthseed$Watch 'Mega Genetics Review: Mendelian and non-Mendelian Genetics' by the Amoeba Sisters (official channel stream) — it revises this whole module with practice problems. Attempt each problem before the solution appears.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=jLmoJPxihjA$wdthseed$, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$X-linked recessive: females need two copies; males need one — males affected more.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod05:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$The X chromosome's gene load, plus males' single copy, makes X-linked recessive traits a male-heavy pattern. Carrier mothers and affected fathers transmit predictably — trace the X's to solve any pedigree.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
