insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod05:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 5 reading: Chapter 12 (Mendel's Experiments) and Chapter 13 (Modern Understandings of Inheritance: sex linkage). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod05:prac$wdthseed$, $wdthseed$Traits in Your Community Survey$wdthseed$, $wdthseed$Collect real inheritance data on observable traits and test whether ratios match genetic predictions.$wdthseed$, $wdthseed$You are a field geneticist surveying at least 30 people (family, friends, classmates).$wdthseed$, $wdthseed$1. Survey 30+ people for THREE traits: tongue rolling (roller/non-roller), earlobe attachment (free/attached), and right/left thumb dominance when clasping hands. 2. Record counts in a table and convert to percentages. 3. For tongue rolling (modelled as dominant R): use the Hardy-Weinberg idea qualitatively — if 75% roll, what does that suggest about allele frequencies? (No calculation required — just argue whether R looks common or rare.) 4. Interview one family: record a trait across two generations and draw a mini-pedigree. 5. Write a conclusion: do your ratios resemble 3:1? Why might small samples deviate? SAFETY & ETHICS: participation voluntary; no names recorded (Person 1, 2...); no tasting of any test papers (some schools use PTC — do NOT use chemicals without teacher supervision).$wdthseed$, $wdthseed$Notebook, pen, willing volunteers.$wdthseed$, $wdthseed$Count tables with percentages, one mini-pedigree, and a 5-sentence conclusion on ratios and sample size.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 75, $wdthseed$TEXT$wdthseed$, $wdthseed$["At least 30 people surveyed across 3 traits with honest counts","Percentages calculated correctly","Conclusion links deviations to sample size and real-world complexity"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod05:asg$wdthseed$, $wdthseed$Genetics Problem Clinic$wdthseed$, $wdthseed$Solve six structured genetics problems and explain one inheritance story in plain language.$wdthseed$, $wdthseed$Solve ALL six with full five-step working (symbols, parents, gametes, square, ratios): 1. Tall (T) × short (tt), all offspring tall — deduce the tall parent's genotype. 2. Black coat (B) dominant in goats: Bb × Bb — ratios? 3. Pink snapdragons self-crossed — offspring phenotypes? 4. Group O mother × group AB father — possible children groups? 5. Carrier haemophilia mother (XHXh) × normal father — probability of affected daughter? 6. Normal parents, colour-blind son — explain with genotypes. Then write 150–200 words explaining to a friend why two brown-eyed parents can have a blue-eyed child (recessive alleles, carriers).$wdthseed$, $wdthseed$Full working for every problem; answers alone earn half marks.$wdthseed$, $wdthseed$Six fully worked crosses + plain-language explanation paragraph.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 120, $wdthseed$TEXT$wdthseed$, $wdthseed$["Correct genotypes/ratios with complete five-step working","Q5/Q6 show correct X-linked reasoning","Explanation uses carrier logic accurately in simple words"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod05$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod05:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
