insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod05:exam:quiz:q05$wdthseed$, $wdthseed$True or False: A father can pass an X-linked gene directly to his son.$wdthseed$, $wdthseed$true_false$wdthseed$, $wdthseed$["True","False"]$wdthseed$::jsonb, $wdthseed$false$wdthseed$::jsonb, $wdthseed$False. Sons receive Y (not X) from their father; their X comes from their mother. Father-to-son transmission rules out X-linkage.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Sex linkage"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod05:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
