insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod05:exam:quiz:q06$wdthseed$, $wdthseed$Which crosses can produce a group O child? (Select ALL that apply)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Group A (IAi) × Group B (IBi)","Group AB × Group O","Group O × Group O","Group A (IAIA) × Group B (IBIB)"]$wdthseed$::jsonb, $wdthseed$["Group A (IAi) × Group B (IBi)","Group O × Group O"]$wdthseed$::jsonb, $wdthseed$O children (ii) need an i from each parent: IAi × IBi can give ii, and O × O always gives ii. AB × O gives only A/B children; IAIA × IBIB gives only AB.$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Blood groups"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod05:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
