insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod06$wdthseed$, $wdthseed$Evolution$wdthseed$, $wdthseed$How life changes over time: natural selection, the evidence for evolution, and the origin of species.$wdthseed$, 6, $wdthseed${"objectives":["Explain natural selection step by step","Evaluate four lines of evidence for evolution","Describe how new species form"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod06:top01$wdthseed$, $wdthseed$Natural Selection$wdthseed$, $wdthseed$Darwin's mechanism: variation, competition, survival and inheritance.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["State the four steps of selection","Apply selection to resistance cases"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod06:top01:les01$wdthseed$, $wdthseed$Darwin's Mechanism$wdthseed$, $wdthseed$How differential survival reshapes populations generation after generation.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=7VM9YxmULuo$wdthseed$, $wdthseed$In 1859 Darwin published an idea so powerful it united all of biology: species change because nature selects. No designer required — just variation, competition and time.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The four steps$wdthseed$, $wdthseed$Natural selection needs four ingredients. (1) VARIATION: individuals differ (Module 4's meiosis guarantees it) — beak sizes, fur shades, enzyme variants. (2) COMPETITION: more offspring are born than can survive (a fish lays millions of eggs; the pond feeds hundreds). (3) DIFFERENTIAL SURVIVAL (selection): individuals whose variants suit the environment survive and breed more — nature 'selects' without intent. (4) INHERITANCE: survivors pass their alleles on, so helpful variants spread and the population's gene pool shifts. Repeat for thousands of generations and populations ADAPT — accumulating traits that fit their world. Darwin inferred this from barnacles, pigeons and Galápagos finches; modern genetics supplied the mechanism he lacked (DNA, mutation, meiosis).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Misconceptions to destroy$wdthseed$, $wdthseed$Three errors lose marks and mislead thinking. (1) 'Individuals evolve' — FALSE: individuals live or die; POPULATIONS evolve as allele frequencies shift. (2) 'Lamarck was right that use and disuse inherits' — FALSE: a blacksmith's muscles do not alter his sperm's DNA; acquired characteristics are NOT inherited (but note: the environment selects among inherited variants). (3) 'Evolution has a purpose or goal' — FALSE: selection is blind, with no foresight — it keeps whatever works NOW. Also reject 'survival of the strongest': it is survival of the FITTEST-TO-THIS-ENVIRONMENT — the fittest bacterium is the one that survives antibiotics, not the biggest. Use allele-frequency language in examinations: 'the resistance allele increased in frequency' beats 'bacteria got stronger'.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: insecticide resistance$wdthseed$, $wdthseed$Question: Mosquitoes in a district survived spraying that killed them five years ago. Explain using natural selection. Step 1 — Variation: a few mosquitoes already carried resistance alleles (from random mutation) BEFORE spraying. Step 2 — Selection pressure: insecticide killed susceptible mosquitoes; resistant ones survived. Step 3 — Inheritance: survivors bred, passing resistance alleles to offspring. Step 4 — Population shift: each generation raised the resistance allele's frequency until most mosquitoes survived. Note what did NOT happen: the spray did not CREATE mutants, and mosquitoes did not 'try' to adapt. This exact logic applies to antibiotic resistance, herbicide-tolerant weeds and pesticide-proof cockroaches.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Natural Selection$wdthseed$, $wdthseed$Watch 'Natural Selection' by the Amoeba Sisters (official channel stream). List the four steps in your own words afterwards, using antibiotic resistance as your example.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=7VM9YxmULuo$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Selection = variation + competition + differential survival + inheritance.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Natural selection turns random variation into adaptation through competition and inheritance. Populations evolve, individuals do not — and resistance cases in hospitals and farms prove the mechanism is running right now.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
