insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod06:top01:les01:vid1:res$wdthseed$, $wdthseed$Natural Selection$wdthseed$, $wdthseed$Natural selection as a mechanism of evolution, with antibiotic-resistance examples.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=7VM9YxmULuo$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod06:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod06:top01:les02$wdthseed$, $wdthseed$Selection in Action Today$wdthseed$, $wdthseed$Antibiotic resistance, sickle cell balance and artificial selection by humans.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Evolution is not ancient history — it is happening in hospitals, farms and mosquito nets this year. Understanding it saves lives.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The antibiotic crisis$wdthseed$, $wdthseed$Bacteria evolve fast: huge populations, 20-minute generations, plus plasmid-swapped genes. Every antibiotic dose is a selection event killing susceptibles; any resistant mutant survives and multiplies. Stopping tablets early is catastrophic: you kill the weak majority but spare the toughest minority, which then recolonise — selecting for resistance with your own body as the laboratory. Hospitals fight back with stewardship (right drug, right dose, FULL course), hygiene (fewer infections = less selection), and combination therapy (multiple drugs = mutants must win several lotteries at once). Tuberculosis, malaria and gonorrhoea already show dangerous resistance in Nigeria and worldwide — completing YOUR prescriptions is a civic duty, not just personal medicine.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Balanced selection and artificial selection$wdthseed$, $wdthseed$Sometimes selection favours BOTH alleles: in malaria zones, HbAHbS carriers resist malaria AND avoid sickle disease, so natural selection maintains the HbS allele despite its cost in homozygotes — BALANCED POLYMORPHISM (heterozygote advantage). Humans also select ARTIFICIALLY: choosing which plants and animals breed. All dogs descend from wolves; maize from teosinte grass; dairy cows give 10x the milk of wild aurochs. Artificial selection is fast and directed (humans choose the pressure), but it narrows gene pools — pedigree dogs inherit disorders, and monoculture crops risk clone crises (Module 4). Modern breeding plus genetic engineering now moves single genes across species (Bt cowpea resists pod borers), raising food-security hopes and biosafety debates.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the unfinished course$wdthseed$, $wdthseed$Question: A patient stops antibiotics on day 3 of 7 because she feels better. Two weeks later the infection returns, now untreatable with the same drug. Explain. Step 1 — The first 3 days killed susceptible bacteria (symptoms faded) but left partially resistant survivors. Step 2 — Without drug pressure, survivors multiplied — now the population is enriched for resistance alleles. Step 3 — The same drug fails because its selection already happened: the remaining bacteria are the selected winners. Lesson: full courses exist to kill even the toughest variants before they breed. (Always follow a doctor's actual prescription — some modern courses ARE short by design.)$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Unfinished antibiotic courses select for resistance — always complete prescriptions.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Selection never sleeps: it breeds superbugs in hospitals, balances sickle cell against malaria, and — directed by humans — created every crop and livestock breed. Knowing the mechanism makes you part of the solution.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod06:top02$wdthseed$, $wdthseed$Evidence and Speciation$wdthseed$, $wdthseed$Fossils, anatomy, embryos, DNA — and how one species becomes two.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Evaluate evolution's evidence","Explain speciation simply"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod06:top02:les01$wdthseed$, $wdthseed$Four Lines of Evidence$wdthseed$, $wdthseed$Fossils, homologous structures, embryos and molecules converge on one conclusion.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A detective convicts with fingerprints, witnesses, CCTV and DNA together — not one clue. Evolution stands on four independent lines of evidence that all point the same way.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Rocks, bodies and embryos$wdthseed$, $wdthseed$(1) FOSSILS: sedimentary rock layers sequence life's history — simple cells deep and old, mammals and flowering plants shallow and young; transitional fossils (Tiktaalik: fish-to-tetrapod; Archaeopteryx: dinosaur-to-bird; Australopithecus: ape-to-human) capture change mid-flight. (2) HOMOLOGOUS STRUCTURES: the pentadactyl limb — human arm, bat wing, whale flipper, mole paw — shares bone-for-bone architecture despite wildly different jobs, proving common ancestry remodelled by selection. Contrast ANALOGOUS structures (bird wing vs insect wing): similar jobs, utterly different builds — convergent evolution, not shared ancestry. Vestigial structures (human appendix and tailbone, flightless birds' wings) are retired remnants. (3) EMBRYOS: vertebrate embryos (fish, chicken, human) all grow pharyngeal slits and tails early — ancestral blueprints revealed before specialisation.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Molecules seal the case$wdthseed$, $wdthseed$(4) MOLECULAR EVIDENCE: DNA and protein sequences measure relatedness precisely — humans share ~99% of DNA with chimpanzees, ~60% with bananas (all life uses the same code). Cytochrome c (a respiration protein) differs by 0 amino acids between humans and chimps but ~45 between humans and yeast — exactly as ancestry predicts. Endogenous retroviruses (ancient viral DNA lodged at IDENTICAL genome positions in related species) are shared scars no designer would duplicate. Converging lines matter because they are INDEPENDENT: fossils could theoretically mislead, but fossils + anatomy + embryos + molecules agreeing by coincidence is inconceivable. This is consilience — science's strongest argument form.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: homology vs analogy$wdthseed$, $wdthseed$Question: A student says bat wings and butterfly wings prove bats and butterflies are closely related. Evaluate. Step 1 — Inspect builds: bat wings are skin stretched over ARM BONES (mammalian pentadactyl limb); butterfly wings are chitin scales with NO bones. Step 2 — Classify: similar function + different structure = ANALOGOUS (convergent evolution for flight), not homologous. Step 3 — Conclude: flight evolved twice independently; DNA places bats with mammals and butterflies with insects — the wings argue nothing about relatedness. Examination rule: homology = same structure (common ancestry); analogy = same job (convergence). Never confuse them.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Fossils sequence life; transitions (Tiktaalik, Archaeopteryx) show change in progress.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Rocks date it, bodies show it, embryos replay it, molecules measure it. Four independent witnesses convict: species share common ancestors and change over time.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod06:top02:les02$wdthseed$, $wdthseed$How Species Split$wdthseed$, $wdthseed$Isolation, divergence and the moment one species becomes two.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$One finch flock reached two Galápagos islands. A million years later, their descendants cannot interbreed. What happened in between is speciation — evolution's creative climax.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The speciation recipe$wdthseed$, $wdthseed$The BIOLOGICAL SPECIES CONCEPT: a species is a group that interbreeds to produce FERTILE offspring (horses + donkeys make sterile mules — different species). ALLOPATRIC speciation (different-homeland) follows four steps: (1) ISOLATION — a barrier (river, mountain, island split) divides one population so gene flow STOPS; (2) DIVERGENCE — each side faces different mutations, selection pressures and drift, so allele frequencies drift apart; (3) ACCUMULATION — differences grow in mating calls, breeding seasons, genitalia, chromosome arrangements; (4) NO RETURN — even if the barrier vanishes, the populations cannot produce fertile offspring: TWO SPECIES. Sympatric speciation (same-homeland, no barrier — e.g. different host plants or breeding times) also occurs but is rarer. Time scales vary: cichlid fishes speciated in thousands of years; mammals usually need millions.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Our own story in four landmarks$wdthseed$, $wdthseed$Human evolution in brief: (1) BIPEDALISM (~6 million years ago): Sahelanthropus and Ardipithecus walk upright in Africa — freeing hands, reshaping spines and pelvises. (2) TOOL CULTURE (~2.6 mya): Homo habilis ('handy man') knaps stone tools; brains expand with meat-eating and cooking. (3) FIRE AND MIGRATION (~1 mya–300 kya): Homo erectus masters fire, grows ~1000cc brains, and leaves Africa. (4) MODERN HUMANS (~300 kya): Homo sapiens evolve in Africa — language, art, agriculture — then spread worldwide, absorbing Neanderthal and Denisovan cousins (non-Africans carry 1–2% Neanderthal DNA). All humanity remains ONE species: any two humans can have fertile children, and our total genetic diversity is smaller than a single chimpanzee troop's.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the river squirrels$wdthseed$, $wdthseed$Question: A river changes course, splitting a squirrel population. 500,000 years later the two groups meet but produce no fertile young. Explain. Step 1 — Isolation: the river stopped gene flow (allopatric start). Step 2 — Divergence: north-side cold selected thick fur; south-side hawks selected camouflage; different mutations accumulated. Step 3 — Reproductive barriers: mating seasons shifted and chromosomes rearranged, so hybrids (if any) are sterile. Step 4 — Verdict: by the biological species concept, speciation is COMPLETE — one species became two. Examination tip: always name the isolation type and end with the fertility test.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Species = interbreeding group producing FERTILE offspring.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod06:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Barriers stop gene flow, selection and drift reshape each side, and sterility seals the split. Humans walked this road from African apes to a single global species in six million years.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod06:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 6 reading: Chapter 18 (Evolution and the Origin of Species) and Chapter 19 (Evolution of Populations). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod06:prac$wdthseed$, $wdthseed$Beaks of the Finches Simulation$wdthseed$, $wdthseed$Demonstrate natural selection by competing 'beak' tools for 'seeds' and tracking survivors over generations.$wdthseed$, $wdthseed$Your table is an island; your tools are beaks; beans are seeds. Drought is coming.$wdthseed$, $wdthseed$1. Gather 3 'beaks' (spoon, forceps/tweezers, toothpick) and 3 'seed' types (30+ each: large beans, rice grains, mixed) scattered on a tray. 2. GENERATION 1 (plenty): each beak feeds 30 seconds; count seeds collected. Any beak collecting fewer than 10 'starves' (eliminated); the winner 'reproduces' (add a second identical beak). 3. GENERATION 2 (drought — remove the easiest seed type): repeat with surviving beaks. 4. Record a table: generation | beak | seeds | survived? 5. Write a conclusion naming the variation, selection pressure, survivors and the allele-frequency shift your simulation models. SAFETY: no real beaks or animals; keep small seeds away from young children (choking hazard).$wdthseed$, $wdthseed$3 tool types, 3 seed types, tray, timer, notebook.$wdthseed$, $wdthseed$Results table for 2 generations + conclusion using variation, selection pressure and inheritance.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["Fair rounds: same time, same seed counts, honest tallies","Table shows elimination and reproduction between generations","Conclusion correctly maps simulation to the four selection steps"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod06:asg$wdthseed$, $wdthseed$The Case for Evolution$wdthseed$, $wdthseed$Write a four-paragraph evidence brief that could convince a sceptical friend.$wdthseed$, $wdthseed$Write 400–500 words in FOUR paragraphs: (1) Fossils — name one transitional fossil and what it shows; (2) Anatomy — explain the pentadactyl limb and one vestigial structure; (3) Molecules — explain how DNA similarity measures relatedness (use the human-chimpanzee figure); (4) Live evolution — describe ONE observed case (antibiotic resistance, peppered moths or Darwin's finch beaks) with the four selection steps. Rules: respectful tone throughout (many people reconcile faith and science — attack no belief); every claim needs its evidence; end with one sentence on why independent lines agreeing matters (consilience).$wdthseed$, $wdthseed$Named examples only — vague 'scientists say' paragraphs score zero.$wdthseed$, $wdthseed$Four-paragraph evidence brief (400–500 words) with named examples.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 100, $wdthseed$TEXT$wdthseed$, $wdthseed$["Four distinct evidence lines with correct named examples","Selection steps applied accurately to the live case","Respectful tone and a consilience closing sentence"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod06$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod06:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
