insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod06:quiz:q01$wdthseed$, $wdthseed$Which sequence correctly orders natural selection?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Inheritance → variation → competition → survival","Variation → competition → differential survival → inheritance","Competition → inheritance → variation → survival","Survival → inheritance → competition → variation"]$wdthseed$::jsonb, $wdthseed$"Variation → competition → differential survival → inheritance"$wdthseed$::jsonb, $wdthseed$Differences must exist first, then compete, then the suited survive and pass alleles on. Any other order breaks the logic.$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Selection"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod06:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
