insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod06:exam:quiz:q01$wdthseed$, $wdthseed$A student says 'giraffes grew long necks by stretching, then passed stretching to calves.' This is wrong because:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Giraffes cannot stretch","Acquired characteristics are not inherited; longer-necked variants survived and passed their alleles","Necks cannot evolve","Only plants evolve"]$wdthseed$::jsonb, $wdthseed$"Acquired characteristics are not inherited; longer-necked variants survived and passed their alleles"$wdthseed$::jsonb, $wdthseed$Lamarckian use-inheritance is false: stretching changes no sperm/egg DNA. Selection among inherited variants explains long necks.$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Selection"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod06:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
