insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod06:exam:quiz:q05$wdthseed$, $wdthseed$Humans and chimpanzees share ~99% of DNA. The best conclusion is:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Humans descended from living chimpanzees","Both share a recent common ancestor (molecular homology)","DNA similarity is meaningless","Chimpanzees will become human"]$wdthseed$::jsonb, $wdthseed$"Both share a recent common ancestor (molecular homology)"$wdthseed$::jsonb, $wdthseed$Similarity measures relatedness through shared ancestry — cousins, not parent and child. No living species is another's ancestor.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Evidence"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod06:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
