insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod06:exam:quiz:q06$wdthseed$, $wdthseed$Which are valid lines of evidence for evolution? (Select ALL that apply)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Transitional fossils appearing in order through rock layers","Identical early embryos across vertebrates","Shared endogenous retroviruses at matching genome positions","The fact that all species look identical"]$wdthseed$::jsonb, $wdthseed$["Transitional fossils appearing in order through rock layers","Identical early embryos across vertebrates","Shared endogenous retroviruses at matching genome positions"]$wdthseed$::jsonb, $wdthseed$Ordered transitions, embryonic similarities and shared viral scars independently confirm common descent. Species plainly do NOT look identical.$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Evidence"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod06:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
