insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod07$wdthseed$, $wdthseed$Ecology$wdthseed$, $wdthseed$How organisms live together: ecosystems, food chains, nutrient cycles, relationships and human impact.$wdthseed$, 7, $wdthseed${"objectives":["Use ecological vocabulary precisely","Construct food chains and explain energy loss","Describe carbon and nitrogen cycles","Evaluate human impact and conservation"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
