insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod07:top01:les01$wdthseed$, $wdthseed$Habitats and Populations$wdthseed$, $wdthseed$The ecological address system: habitat, population, community, ecosystem, biome.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A tilapia's world is water temperature, dissolved oxygen, algae to eat and fishermen to avoid. Ecology maps these worlds — and what happens when they change.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The address system$wdthseed$, $wdthseed$HABITAT: where an organism lives (a fishpond, a mango canopy). POPULATION: all members of ONE species in a habitat (all tilapia in the pond). COMMUNITY: ALL populations sharing the habitat (tilapia + catfish + algae + water insects). ECOSYSTEM: community PLUS non-living surroundings (water, mud, sunlight, dissolved oxygen). BIOME: a continental-scale ecosystem type (tropical rainforest, savanna, desert). NICHE: an organism's ROLE — what it eats, what eats it, when it is active (no two species hold identical niches for long — competition excludes one). Factors splitting the world: BIOTIC (living: predation, competition, disease, food supply) and ABIOTIC (non-living: light, temperature, water, pH, salinity, oxygen). Examination habit: always classify factors before explaining effects.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les01:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: why did the fish die?$wdthseed$, $wdthseed$Question: After hot harmattan weeks, fish die in a shallow pond though no poison is found. Explain using abiotic factors. Step 1 — Identify the factor: high temperature LOWERS dissolved oxygen in water (warm water holds less gas) while fish metabolism (oxygen demand) RISES. Step 2 — Link: demand exceeds supply, especially at night when algae also respire. Step 3 — Conclude: fish suffocate — an abiotic (temperature/oxygen) population crash with no disease needed. Management moral: shade, aeration or deeper ponds buffer the factor. Examiners award the gas-solubility link specifically — memorise it.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les01:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Habitat (address) → population (one species) → community (all species) → ecosystem (+ non-living) → biome (continental).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les01:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Ecology's vocabulary maps where organisms live and what constrains them. Populations answer to both living neighbours and non-living conditions — and a single abiotic shift can crash a pond.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod07:top01:les02$wdthseed$, $wdthseed$Food Chains and Energy Flow$wdthseed$, $wdthseed$Producers to top predators: why energy pyramids narrow and chains stay short.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$It takes roughly 10 kg of grain to make 1 kg of beef. Follow the energy and you will understand farming, famine and why there are no six-metre spiders.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Trophic levels$wdthseed$, $wdthseed$PRODUCERS (autotrophs — grass, algae) capture sunlight. PRIMARY CONSUMERS (herbivores — grasshopper, tilapia fry) eat producers. SECONDARY CONSUMERS (small carnivores — frog, catfish) eat herbivores. TERTIARY CONSUMERS (top predators — hawk, crocodile) eat carnivores. DECOMPOSERS (bacteria, fungi) digest dead matter and waste at EVERY level, recycling nutrients. Arrows point IN THE DIRECTION OF ENERGY FLOW (food → feeder): grass → grasshopper → frog → snake → hawk. Real feeding is a WEB (owls eat both mice and frogs), but chains isolate one path for analysis. TROPHIC LEVEL = feeding step counted from producers (level 1).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why pyramids narrow$wdthseed$, $wdthseed$Only ~10% of energy transfers between levels: most is lost to RESPIRATION (movement, warmth, metabolism), UNEATEN parts (roots, bones), INEDIBLE parts (bark, fur) and EXCRETION (urine, faeces, egested fibre). Consequences: (1) food chains rarely exceed 4–5 levels — too little energy remains; (2) top predators are few (one lion needs thousands of kg of grass via zebras); (3) eating lower (grains, beans) feeds more people per hectare than beef — a food-security arithmetic every policymaker should know. PYRAMIDS: energy pyramids ALWAYS narrow upward; biomass pyramids usually narrow (but can invert — e.g. tiny fast-reproducing phytoplankton supporting heavier zooplankton); number pyramids can invert (one tree feeding thousands of insects). Biomagnification runs opposite: persistent toxins (mercury, some pesticides) CONCENTRATE upward, poisoning top predators most.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the missing energy$wdthseed$, $wdthseed$Question: A grassland fixes 20,000 kJ/m²/year. Zebras gain 1,800 kJ; lions gain 160 kJ. Calculate both transfer efficiencies and account for the losses. Step 1 — Efficiencies: zebra 1800/20000 = 9%; lion 160/1800 ≈ 9%. Step 2 — Losses: grass respiration + uneaten roots + zebra respiration/movement/dung + lion respiration/movement/indigestible parts. Step 3 — Conclude: ~9% matches the 10% rule; each level keeps roughly one-tenth. Examination format: show the division, convert to %, then name at least THREE loss routes — respiration is compulsory in the list.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Arrows show ENERGY flow: food → feeder. Decomposers recycle at every level.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Energy enters through producers and leaks ~90% at every step, shaping short chains, rare predators and the arithmetic of feeding humanity. Toxins, perversely, concentrate where energy fades.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod07:top02$wdthseed$, $wdthseed$Cycles and Relationships$wdthseed$, $wdthseed$Carbon and nitrogen cycles; predation, competition and symbiosis.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Trace both nutrient cycles","Classify species relationships"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod07:top02:les01$wdthseed$, $wdthseed$Carbon and Nitrogen Cycles$wdthseed$, $wdthseed$How the same atoms circulate through air, life and soil forever.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=NHqEthRCqQ4$wdthseed$, $wdthseed$The carbon in your body was once dinosaur breath, ancient forest and ocean limestone. Atoms recycle endlessly — today's cycles are tomorrow's dinner.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The carbon cycle$wdthseed$, $wdthseed$Atmospheric CO2 enters life through PHOTOSYNTHESIS (producers). Carbon then moves through FEEDING (herbivores → carnivores), returns to air via RESPIRATION (all living cells), DECOMPOSITION (decomposers respiring dead matter), and COMBUSTION (burning wood, fossil fuels, bush fires). Oceans exchange CO2 at the surface; long-term stores (limestone, fossil fuels, peat) lock carbon for millennia. Humans unbalance the cycle by burning fossil stores millions of times faster than they formed — raising CO2, trapping heat (greenhouse effect) and acidifying oceans. Planting trees and protecting forests re-lock carbon; burning bush and flaring gas accelerate the imbalance.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The nitrogen cycle$wdthseed$, $wdthseed$Nitrogen gas (78% of air) is unusable directly — the triple bond defeats most life. Bacteria run the cycle: (1) NITROGEN FIXATION — Rhizobium in legume root nodules (beans, soya, groundnuts) and free-living Azotobacter convert N2 to ammonia; lightning fixes some too. (2) NITRIFICATION — Nitrosomonas convert ammonia → nitrites, then Nitrobacter convert nitrites → NITRATES, which plants absorb. (3) ASSIMILATION — plants build nitrates into amino acids and proteins; animals gain nitrogen by eating plants. (4) AMMONIFICATION/DECOMPOSITION — decomposers return nitrogen from dead matter, urine and faeces as ammonia. (5) DENITRIFICATION — anaerobic Pseudomonas convert nitrates BACK to N2 gas in waterlogged soils (a fertility loss farmers dread). Crop rotation with beans exploits fixation free of charge — traditional wisdom validated by microbiology.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the green, stinking lake$wdthseed$, $wdthseed$Question: Fertiliser runoff enters a lake. Within weeks the water turns green, smells, and fish die. Explain (eutrophication). Step 1 — Nitrates/phosphates fertilise ALGAE → algal bloom (green water) blocking light; submerged plants die. Step 2 — Dead algae and plants feed DECOMPOSER bacteria, which multiply and RESPIRE heavily. Step 3 — Bacterial respiration strips dissolved OXYGEN (especially at night) → fish suffocate; anaerobic decay releases stinking gases (hydrogen sulphide). Step 4 — Conclude: nutrient enrichment → bloom → decomposition → deoxygenation → death. Prevention: buffer strips, precise fertiliser dosing, and treating sewage before discharge.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Carbon and Nitrogen Cycles$wdthseed$, $wdthseed$Watch 'Carbon and Nitrogen Cycles' by the Amoeba Sisters (official channel stream). Draw both cycles from memory afterwards, naming the bacteria in the nitrogen cycle.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=NHqEthRCqQ4$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Carbon: photosynthesis in; respiration, decomposition, combustion out.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Carbon cycles through air and life in years; nitrogen cycles through bacterial middlemen in soils. Both cycles feed us — and both punish careless fertiliser and fuel use.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
