insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod07:top02:les01:vid1:res$wdthseed$, $wdthseed$Carbon and Nitrogen Cycles$wdthseed$, $wdthseed$Both nutrient cycles with reservoirs, bacteria and human disruptions.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=NHqEthRCqQ4$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod07:top02$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod07:top02:les02$wdthseed$, $wdthseed$How Species Relate$wdthseed$, $wdthseed$Predation, competition and the three symbioses — mutualism, commensalism, parasitism.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=rNjPI84sApQ$wdthseed$, $wdthseed$Oxpeckers ride cattle eating ticks; mistletoe strangles orange trees; lions and leopards hunt the same antelope. Every ecosystem is a web of deals, thefts and wars.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Five relationships$wdthseed$, $wdthseed$PREDATION (+/−): hunter kills prey (lion/antelope, praying mantis/housefly) — drives cycles and natural selection. COMPETITION (−/−): both sides lose fitness fighting for the same resource — intraspecific (two yam seedlings crowding) is fiercest since needs match exactly; interspecific (goats vs cattle on grass) can exclude one species. MUTUALISM (+/+): both benefit — Rhizobium fixes nitrogen for beans while beans feed it sugars; oxpeckers clean cattle of ticks; gut bacteria digest fibre for us. COMMENSALISM (+/0): one benefits, the other unaffected — epiphytic ferns perch on trees for light; cattle egrets eat insects flushed by grazing herds. PARASITISM (+/−): parasite benefits, host suffers — Plasmodium (malaria), tapeworms, ticks, mistletoe on citrus. Grade relationships by FITNESS EFFECTS (+/−), not feelings.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Predator-prey cycles$wdthseed$, $wdthseed$Predator and prey populations oscillate in linked waves: many prey → predators feast and breed → many predators over-eat prey → prey crash → predators starve → few predators let prey recover — the cycle repeats with predators LAGGING behind prey (classic lynx-hare graphs). Human interference (pesticides killing predators, overfishing prey) breaks cycles and triggers plagues or collapses. Biological control EXPLOITS predation deliberately: ladybirds vs aphids, Bacillus thuringiensis vs mosquito larvae — pest control with minimal chemicals when done scientifically.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: classifying relationships$wdthseed$, $wdthseed$Question: Classify: (a) tapeworm in a child's gut, (b) egret following cattle, (c) lichen (fungus + alga). Step 1 — Score fitness effects: (a) worm gains food/shelter, child loses nutrients → (+/−) PARASITISM. (b) Egret gains flushed insects; cattle unaffected → (+/0) COMMENSALISM. (c) Fungus shelters algae; algae photosynthesise sugars for both → (+/+) MUTUALISM. Step 2 — Justify each with the benefit/harm mechanism. Examination trap: mutualism needs PROVEN two-way benefit — 'living together' alone is just symbiosis in the broad sense.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Ecological Relationships$wdthseed$, $wdthseed$Watch 'Ecological Relationships' by the Amoeba Sisters (official channel stream). Afterwards, classify five relationships you have personally observed at home or in the market.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=rNjPI84sApQ$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Predation +/−, competition −/−, mutualism +/+, commensalism +/0, parasitism +/−.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top02:les02:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Species deal in five currencies from mutual profit to outright theft. Predator-prey cycles breathe through ecosystems, and wise farmers and doctors turn these relationships into tools.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
