insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod07:top03$wdthseed$, $wdthseed$Humans and the Environment$wdthseed$, $wdthseed$Pollution, habitat loss and climate change — and what conservation can do.$wdthseed$, NULL, 3, TRUE, TRUE, $wdthseed${"objectives":["Assess major human impacts","Propose conservation actions"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod07:top03:les01$wdthseed$, $wdthseed$Impact and Conservation$wdthseed$, $wdthseed$Deforestation, pollution, overharvesting and climate change — causes, effects and solutions.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Nigeria loses hundreds of thousands of hectares of forest yearly; Lagos traffic chokes the air; the Sahel creeps south. Ecology without action is just watching — this lesson demands solutions.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top03:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Four impacts$wdthseed$, $wdthseed$(1) DEFORESTATION: logging, farming and fuelwood remove forests → biodiversity loss, soil erosion (no roots to hold soil), flooding, and CO2 release (fewer absorbers + burning). (2) POLLUTION: oil spills smother mangroves and fisheries (Niger Delta); plastic chokes drains and livestock; industrial effluent poisons rivers; vehicle exhaust harms lungs. (3) OVERHARVESTING: taking faster than replacement — overfishing collapses stocks (smaller catches yearly), bushmeat hunting empties forests ('empty forest syndrome'). (4) CLIMATE CHANGE: fossil-fuel CO2 traps heat → rising temperatures, erratic rainfall, sea-level rise threatening Lagos and the Delta, and shifting disease zones (malaria climbing to highlands). Each impact hits the poorest first — environmental damage is a justice issue.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top03:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Conservation that works$wdthseed$, $wdthseed$PRESERVATION locks nature away untouched; CONSERVATION manages use sustainably (harvest below replacement rate). Working tools: PROTECTED AREAS (Yankari, Cross River parks) guard biodiversity cores; REFORESTATION and agroforestry rebuild cover and income; SUSTAINABLE FISHING (size limits, closed seasons, no dynamite) lets stocks recover; WASTE MANAGEMENT (reduce, reuse, recycle; proper dumps, not drains); CLEAN ENERGY (solar leapfrogs grids); and EDUCATION — the multiplier of all the rest. Conservation succeeds when locals benefit: ecotourism jobs, beekeeping buffers, community forests. Your assignment investigates one local issue and proposes exactly such a plan.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top03:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: the disappearing forest$wdthseed$, $wdthseed$Question: A village clears riverside forest for yam mounds. Two years later: yam yields fall, the stream floods yearly, and fish vanish. Explain and propose fixes. Step 1 — Diagnose: no tree roots → soil ERODES into the stream (silt smothers fish eggs); no canopy → rain hits soil directly (flooding); no leaf litter → soil fertility CRASHES (yields fall). Step 2 — Prescribe: replant riverbank buffer trees (roots + shade), practise alley cropping (yam between nitrogen-fixing hedges), and ban farming within 10 m of the stream. Step 3 — Generalise: every symptom traces to removing the forest's free services — conservation is enlightened self-interest.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top03:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Deforestation → erosion + floods + CO2. Pollution → dead zones + disease. Overharvesting → collapse. Climate change → heat + erratic rain + rising seas.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod07:top03:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Human impacts share one root: consuming natural capital faster than it renews. Conservation — protected areas, sustainable harvests, clean energy, educated citizens — is how civilisation pays its ecological bills.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod07:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 7 reading: Chapters 42–44 (Ecosystems, Populations, Conservation). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod07:prac$wdthseed$, $wdthseed$Compound Biodiversity Audit$wdthseed$, $wdthseed$Estimate plant populations with quadrats and compare biodiversity between two areas.$wdthseed$, $wdthseed$You are an ecologist comparing a trampled path edge with an undisturbed corner.$wdthseed$, $wdthseed$1. Make a quadrat: 4 sticks + string forming a 50 cm × 50 cm square. 2. Throw it RANDOMLY (over your shoulder, no choosing) 5 times in AREA A (disturbed: path/football edge) and 5 times in AREA B (undisturbed: garden corner/bush edge). 3. In each throw, count every plant species (grass, weed types — name or sketch) and individuals per species. 4. Record: throw | species | counts. Calculate mean plants per quadrat and species count per area. 5. Conclude: which area is more diverse/abundant, and link to trampling, light or soil (abiotic factors). SAFETY: watch for thorns, ants and broken glass; wear closed shoes; wash hands.$wdthseed$, $wdthseed$4 sticks, string, notebook, closed shoes.$wdthseed$, $wdthseed$Two 5-throw data tables with means + conclusion naming the likely causal factors.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 75, $wdthseed$TEXT$wdthseed$, $wdthseed$["Random placement honestly done (no cherry-picking)","Complete tables with means calculated","Conclusion links differences to specific biotic/abiotic factors"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod07:asg$wdthseed$, $wdthseed$My Environment, My Plan$wdthseed$, $wdthseed$Investigate one real local environmental problem and write a costed, realistic action plan.$wdthseed$, $wdthseed$1. Choose ONE issue near you: blocked drains, refuse dumps, tree loss, stream pollution, erosion, smoke, or overfishing. 2. EVIDENCE: describe what you observe (photos described, locations, who is affected, since when) — 150 words. 3. ECOLOGY: explain the biological mechanism (eutrophication? erosion? biomagnification? habitat loss?) — 150 words. 4. PLAN: propose 3 actions with WHO does WHAT, rough COST (free/cheap/expensive), and how success is MEASURED — 200 words. 5. Submit 500–600 words total. Real places and real numbers score highest.$wdthseed$, $wdthseed$Must be a real place you have visited; invented issues score zero.$wdthseed$, $wdthseed$Evidence + mechanism + 3-action plan (500–600 words).$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 120, $wdthseed$TEXT$wdthseed$, $wdthseed$["Concrete local evidence (place, observations, affected people)","Correct ecological mechanism explained","Three realistic actions with owners, costs and success measures"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod07$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod07:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
